fn solve(t: Vec<char>) -> Vec<char> {
    // Assumption from the problem statement: t is non-empty.
    // We still handle the empty case safely.
    let n = t.len();
    let mut out: Vec<char> = Vec::with_capacity(n);

    // Measure for termination: elements left to process = n - i,
    // which strictly decreases each iteration because i increases by 1.
    let mut i: usize = 0;
    while i < n {
        out.push(t[i]);
        i += 1;
    }

    // Ensures the output has exactly the same length as the input.
    debug_assert_eq!(out.len(), n);
    out
}